       MT3(577)   = 4.53111306e-02
       MT3(578)   = -4.23226361e-02
       MT3(579)   = 6.09751286e-02
       MT3(580)   = -4.61104205e-02
       MT3(581)   = -4.82588314e-02
       MT3(582)   = 4.74145898e-02
       MT3(583)   = -4.80040619e-02
       MT3(584)   = -5.01986082e-02
       MT3(585)   = -6.84377724e-02
       MT3(586)   = -5.73652554e-02
       MT3(587)   = 4.82614784e-02
       MT3(588)   = 4.77580514e-02
       MT3(589)   = -2.44032022e-02
       MT3(590)   = -3.46180776e-02
       MT3(591)   = -3.18015971e-02
       MT3(592)   = 6.35341715e-02
       MT3(593)   = 6.78958167e-02
       MT3(594)   = -4.87300246e-02
       MT3(595)   = -4.88232537e-02
       MT3(596)   = 3.23892247e-02
c
c
      do k = 1, nblock ! Loop over all blocks
         pxval = zero
         pyval = zero
         pzval = zero
c
         if (amplitude .gt. zero) then
c
             dex2q = (curCoords(k,1)-xmin)/(xend-xendm1)+one
             dex1q = (curCoords(k,2)-ymin)/(yend-yendm1)+one
             dex3q = (curCoords(k,3)-zmin)/(zend-zendm1)+one
c
             cosAx = cos(PI*(pxdex(1:521) - one)*(two*dex1q-one)/(two*6.600000e+01))
             cosBx = cos(PI*(qxdex(1:521) - one)*(two*dex2q-one)/(two*7.400000e+01))
             cosCx = cos(PI*(rxdex(1:521) - one)*(two*dex3q-one)/(two*5.000000e+01))
             costermsx = cosAx*cosBx*cosCx
             pxval = sum(MT1*costermsx)
c
             cosAy = cos(PI*(pydex(1:578) - one)*(two*dex1q-one)/(two*6.600000e+01))
             cosBy = cos(PI*(qydex(1:578) - one)*(two*dex2q-one)/(two*7.400000e+01))
             cosCy = cos(PI*(rydex(1:578) - one)*(two*dex3q-one)/(two*5.000000e+01))
             costermsy = cosAy*cosBy*cosCy
             pyval = sum(MT2*costermsy)
c
             cosAz = cos(PI*(pzdex(1:596) - one)*(two*dex1q-one)/(two*6.600000e+01))
             cosBz = cos(PI*(qzdex(1:596) - one)*(two*dex2q-one)/(two*7.400000e+01))
             cosCz = cos(PI*(rzdex(1:596) - one)*(two*dex3q-one)/(two*5.000000e+01))
             costermsz = cosAz*cosBz*cosCz
             pzval = sum(MT3*costermsz)
c
          end if
c
c
         pval = pxval*dircos(k,3,1)+pyval*dircos(k,3,2)+pzval*dircos(k,3,3)
         value(k) = -1.e-2*pval*amplitude
       end do
c
c
       return
       end
